import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { ZimmInlineMessage } from '.';

/**
 * Five stories, deliberately overlapping variant+copy in places (per this build step's own
 * brief: "your call on exact story count/naming, as long as every one of the 3 exact strings and
 * both variants gets a real story") rather than inventing a fourth, non-canonical example string:
 * `Default`/`ErrorVariant`/`PartiallyOutOfStock` cover `error`; `Warning`/`MaxQuantityReached`
 * cover `warning` — every one of the three exact copy strings (SFCC-795 §11.2) appears at least
 * once, and both variants render at least once each.
 */
const meta: Meta<typeof ZimmInlineMessage> = {
  // Elements/, not Commerce/ — per components.md's own tiebreaker ("what does this component
  // know about?"): the prop surface is variant + text only, nothing product/cart/price-specific,
  // the same generic shape as Badge/Tag/Link. Its one caller today (ProductItem) is commerce
  // context, but that doesn't make the atom itself commerce-specific.
  title: 'Elements/ZimmInlineMessage',
  component: ZimmInlineMessage,
  parameters: { layout: 'padded' },
};

export default meta;
type Story = StoryObj<typeof ZimmInlineMessage>;

/** Fully out-of-stock — error variant, exact copy #1. */
export const Default: Story = {
  args: {
    variant: 'error',
    text: 'This item is unavailable',
  },
};

/** Named for the variant itself (`ErrorVariant`, not the bare `Error` identifier — that would
 *  shadow the built-in JS `Error` global within this module), distinct copy from `Default`
 *  (partial-OOS's string) so no two stories share identical args. */
export const ErrorVariant: Story = {
  args: {
    variant: 'error',
    text: 'Quantity unavailable in this size',
  },
};

/** Named `Warning` for the variant itself. Also the max-quantity copy — see zimmInlineMessage.css.ts
 *  for why this is `warning`, not `error`, despite the requirement text's own wording. */
export const Warning: Story = {
  args: {
    variant: 'warning',
    text: 'Maximum purchase quantity reached for this size',
  },
};

/** Partial OOS — error variant, exact copy #2. */
export const PartiallyOutOfStock: Story = {
  args: {
    variant: 'error',
    text: 'Quantity unavailable in this size',
  },
};

/** Max quantity reached — warning variant, exact copy #3. */
export const MaxQuantityReached: Story = {
  args: {
    variant: 'warning',
    text: 'Maximum purchase quantity reached for this size',
  },
};

