/**
 * SFCC-795 (plan step 3.2). This atom's own render contract: does `aria-live="polite"` actually
 * render, does `data-testid` exist, does `text` render verbatim, and does `variant` actually
 * reach `useMultiStyleConfig` (proving the two variants resolve to genuinely different values,
 * not just that two differently-named keys exist in the recipe). Per testing.md's own guidance,
 * this contract must be provable from this component's own folder, not only incidentally via
 * product-item/index.test.tsx (which doesn't assert aria-live at all).
 *
 * SFCC-795 rework (Marcel's own visual checkpoint against the real Figma file): the `warning`
 * variant now renders a leading icon, `error` never does. `ZimmIcon` genuinely throws under real
 * Vitest rendering — it imports the base SFCC icons barrel, which has a top-level side effect
 * incompatible with this test environment (testing.md's documented "Known gap: ZimmIcon throws
 * under Vitest") — so it's mocked at the smallest surface, the same established pattern
 * footerNavColumn/index.test.tsx and zimmSubscribeSection/index.test.tsx already use, adjusted
 * here to forward `type` (rather than `aria-label`/`aria-hidden`, which neither of those two
 * examples needed to check) since the two new tests below assert on exactly that.
 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import theme from 'app/theme';
import { ZimmInlineMessage } from '.';

vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: (props: { type: string }) => <div data-testid="mock-info-icon" data-type={props.type} />,
}));

const renderWithTheme = (ui: React.ReactElement) => render(<ChakraProvider theme={theme}>{ui}</ChakraProvider>);

describe('ZimmInlineMessage', () => {
  test('renders the given text verbatim', () => {
    renderWithTheme(<ZimmInlineMessage variant="error" text="This item is unavailable" />);
    expect(screen.getByText('This item is unavailable')).toBeInTheDocument();
  });

  test('carries aria-live="polite" so a shopper using assistive tech is told about it without a focus move', () => {
    renderWithTheme(<ZimmInlineMessage variant="warning" text="Maximum purchase quantity reached for this size" />);
    expect(screen.getByTestId('zimm-inline-message')).toHaveAttribute('aria-live', 'polite');
  });

  test('error and warning variants resolve to genuinely different colours, not just different variant keys', () => {
    const { unmount } = renderWithTheme(<ZimmInlineMessage variant="error" text="Quantity unavailable in this size" />);
    const errorColor = getComputedStyle(screen.getByTestId('zimm-inline-message')).color;
    unmount();

    renderWithTheme(<ZimmInlineMessage variant="warning" text="Quantity unavailable in this size" />);
    const warningColor = getComputedStyle(screen.getByTestId('zimm-inline-message')).color;

    expect(errorColor).not.toBe(warningColor);
  });

  // SFCC-795 rework pass criterion: warning carries the icon, confirmed against the 3 Figma
  // cart-item instances cited in this component's own docblock and in zimmInlineMessage.css.ts.
  test('variant="warning" renders the info-solid icon', () => {
    renderWithTheme(<ZimmInlineMessage variant="warning" text="Maximum purchase quantity reached for this size" />);
    const icon = screen.getByTestId('mock-info-icon');
    expect(icon).toBeInTheDocument();
    expect(icon).toHaveAttribute('data-type', 'info-solid');
  });

  test('variant="error" never renders the icon', () => {
    renderWithTheme(<ZimmInlineMessage variant="error" text="This item is unavailable" />);
    expect(screen.queryByTestId('mock-info-icon')).not.toBeInTheDocument();
  });
});

