4	/**
5	 * Recipe wiring — SFCC-795 §11.2 pass criteria 2 and 6. Reads the exported recipe object
6	 * directly so these assert the real resolved token references, not a rendered component's
7	 * computed style (jsdom does not reliably resolve custom-property values) and not a hardcoded
8	 * hex duplicate of the foundation source.
9	 *
10	 * SFCC-795 rework: the recipe moved from a single-node `defineStyleConfig` to a two-part
11	 * (`root`/`text`) plain-object recipe (see zimmInlineMessage.css.ts's own docblock) — every
12	 * property path below was updated to read through the owning part; the underlying claim each
13	 * test makes (status-error/text-muted tokens not hardcoded hex, regular-weight override, full
14	 * width, exactly two variants) is unchanged.
15	 */
16	describe('ZimmInlineMessage — recipe wiring', () => {
17	  test('error variant resolves to the real status-error colour token var, not a hardcoded hex', () => {
18	    // No `!`/`as` here (unlike baseStyle below): now that this recipe is a plain object literal
19	    // (SFCC-795 rework, no more `defineStyleConfig` wrapper), TypeScript infers `variants` and its
20	    // two keys precisely enough on their own that ESLint's no-unnecessary-type-assertion rule
21	    // flags both as redundant — confirmed by running lint, not assumed.
22	    const error = ZimmInlineMessage.variants.error;
23	    expect(error.root.color).toBe('var(--zimm-color-status-error)');
24	    expect(error.root.color).not.toMatch(/#/);
25	  });
26	
27	  test('warning variant resolves to the real muted-text colour token var, not a hardcoded hex', () => {
28	    const warning = ZimmInlineMessage.variants.warning;
29	    expect(warning.root.color).toBe('var(--zimm-color-text-muted)');
30	    expect(warning.root.color).not.toMatch(/#/);
31	  });
32	
33	  test('no low-stock (or any third) variant exists in the recipe', () => {
34	    expect(Object.keys(ZimmInlineMessage.variants).sort()).toEqual(['error', 'warning']);
35	  });
36	
37	  test('caption textStyle is overridden to regular weight, not left at its medium default', () => {
38	    const base = ZimmInlineMessage.baseStyle as { text: Record<string, unknown> };
39	    expect(base.text.textStyle).toBe('caption');
40	    expect(base.text.fontWeight).toBe('var(--zimm-font-weight-regular)');
41	  });
42	
43	  test('spans the full row width, matching the Figma "w-full" annotation', () => {
44	    const base = ZimmInlineMessage.baseStyle as { root: Record<string, unknown> };
45	    expect(base.root.width).toBe('full');
46	  });
47	
48	  // SFCC-795 rework: declares exactly the two parts the component actually reads —
49	  // recipeParts.test.ts reconciles this against index.tsx's own `styles.root`/`styles.text`
50	  // reads. No separate `icon` part — see zimmInlineMessage.css.ts's own docblock for why.
51	  test('declares exactly the root and text parts, no more, no less', () => {
52	    expect(ZimmInlineMessage.parts).toEqual(['root', 'text']);
53	  });
54	});
