1	/**
2	 * Recipe guards — regression tests for four failure modes that reached a feature branch
3	 * despite passing `tsc`, `eslint`, `vitest`, CodeRabbit and the Storybook a11y run.
4	 *
5	 * All four share a shape: the value is a *valid* `SystemStyleObject` entry, so TypeScript is
6	 * satisfied; no lint rule covers it; and nothing asserts layout. Each one renders plausible,
7	 * wrong output that is only visible by opening the page.
8	 *
9	 *   1. A spacing-scale key on a sizing property. Chakra resolves `width`/`height`/`boxSize`
10	 *      through `theme.sizes`, not `theme.space`. The Zimmermann named scale is registered as
11	 *      `space` only (deliberately — see foundation/sizes.ts), so `width: 'xl'` silently reads
12	 *      Chakra's default `sizes.xl` = 36rem. It shipped a 576px icon and collapsed the footer.
13	 *
14	 *   2. The same trap on a typography property. `fontSizes`/`lineHeights`/`letterSpacings` are
15	 *      deliberately NOT registered either (theme/index.ts explains why), so a bare key reads
16	 *      Chakra's default or resolves to nothing at all. See TYPOGRAPHY_PROPS below.
17	 *
18	 *   3. A recipe key that collides with a base SFCC recipe. `theme/index.ts` composes with
19	 *      `extendTheme(baseTheme, overrides)`, which DEEP MERGES — a recipe named `Footer` does
20	 *      not replace SFCC's `Footer`, it inherits it. Shared part names then pick up base
21	 *      properties, and a key you add that the base lacks is appended last, so a CSS shorthand
22	 *      can silently reset a longhand the base declared earlier.
23	 *
24	 *   4. A bare scale key inside a compound shorthand. Chakra resolves a token only when it is
25	 *      the entire value; `padding: 'xs 0'` is emitted verbatim, the browser rejects the
26	 *      declaration, and the padding does not apply at all.
27	 *
28	 * A fifth guard below (`no override-component style uses a bare token key on a registered
29	 * scale`) is a different kind of check — not a wrong-value bug, since `space` and `colors`
30	 * ARE registered Chakra scales (theme/index.ts), so a bare key there resolves to the correct
31	 * Zimmermann value either way. It enforces a house style instead: override components must
32	 * always reference a zimm value via `var(--zimm-scale-*)` / `var(--zimm-color-*)`, never a
33	 * bare Chakra token string, so a PR reviewer sees an unambiguous zimm reference at every call
34	 * site instead of having to recall which scales are and are not registered.
35	 *
36	 * SCOPE: these guards walk the registered recipe map only (`components` + the composed
37	 * `theme`). They cannot see the same mistakes made as a JSX prop on a component — there is a
38	 * live instance of failure mode 2 at `overrides/app/components/header/index.tsx:302`
39	 * (`fontSize="l"`, which emits nothing) that no test here can reach. Catching that class needs
40	 * a static rule over JSX attributes (`.coderabbit/ast-grep-rules/`), not a theme walk. The
41	 * house-style guard has the same JSX blind spot — `footerNavColumn/index.tsx` had a bare
42	 * `paddingLeft: '2xs'` in an inline `sx` merge (not a recipe) that this test cannot see;
43	 * it was only found by a manual grep across `overrides/app/components/`, not by this suite.
44	 */
45	import { describe, expect, test } from 'vitest';
46	import theme from '../index';
47	import { components } from './index';
48	import { breakpoints } from '../foundation/gridSystem';
49	import { fontSizes, letterSpacings, lineHeights } from '../foundation/typography';
50	import { spacing } from '../foundation/spacing';
51	import { colors } from '../foundation/colour';
52	
53	const SPACING_KEYS = Object.keys(spacing);
54	
55	/**
56	 * Recursively flattens a nested token object into dot-joined path strings — 'text.default',
57	 * 'action.primary.bgDefault', etc. — mirroring exactly how a recipe would reference it bare
58	 * (`color: 'text.default'`).
59	 */
60	const flattenKeys = (obj: Record<string, unknown>, prefix = ''): string[] =>
61	  Object.entries(obj).flatMap(([key, value]) => {
62	    const path = prefix ? `${prefix}.${key}` : key;
63	    return typeof value === 'object' && value !== null ? flattenKeys(value as Record<string, unknown>, path) : [path];
64	  });
65	
66	const COLOR_KEYS = new Set(flattenKeys(colors as unknown as Record<string, unknown>));
67	
68	/** Every Chakra prop that resolves through the registered `theme.space` scale — the full
69	 *  padding/margin/gap/inset family, including directional and logical variants. */
70	const SPACE_PROPS = new Set([
71	  'padding',
72	  'margin',
73	  'gap',
74	  'inset',
75	  'p',
76	  'm',
77	  'px',
78	  'py',
79	  'mx',
80	  'my',
81	  'pt',
82	  'pb',
83	  'pl',
84	  'pr',
85	  'mt',
86	  'mb',
87	  'ml',
88	  'mr',
89	  'paddingTop',
90	  'paddingBottom',
91	  'paddingLeft',
92	  'paddingRight',
93	  'paddingBlock',
94	  'paddingInline',
95	  'paddingBlockStart',
96	  'paddingBlockEnd',
97	  'paddingInlineStart',
98	  'paddingInlineEnd',
99	  'marginTop',
100	  'marginBottom',
101	  'marginLeft',
102	  'marginRight',
103	  'marginBlock',
104	  'marginInline',
105	  'marginBlockStart',
106	  'marginBlockEnd',
107	  'marginInlineStart',
108	  'marginInlineEnd',
109	  'top',
110	  'left',
111	  'right',
112	  'bottom',
113	]);
114	
115	/** Every Chakra prop that resolves through the registered `theme.colors` scale. */
116	const COLOR_PROPS = new Set([
117	  'color',
118	  'backgroundColor',
119	  'bg',
120	  'background',
121	  'borderColor',
122	  'outlineColor',
123	  'fill',
124	  'stroke',
125	]);
126	
127	const SIZING_PROPS = new Set([
128	  'width',
129	  'height',
130	  'minWidth',
131	  'maxWidth',
132	  'minHeight',
133	  'maxHeight',
134	  'boxSize',
135	  'w',
136	  'h',
137	  'minW',
138	  'maxW',
139	  'minH',
140	  'maxH',
141	]);
142	
143	/**
144	 * Typography properties whose Zimmermann scale is deliberately not registered as a Chakra
145	 * scale, mapped to the keys that must never appear bare on them. Each set is that property's
146	 * own Zimmermann scale keys ∪ the spacing keys, because both spellings fail — differently:
147	 *
148	 *   fontSize: '2xs' → resolves against Chakra's default fontSizes: 0.625rem (10px), where the
149	 *                     Zimmermann `2xs` (0.875rem / 14px) was intended. Plausible, wrong size.
150	 *   fontSize: '4xs' → no Chakra key, so `font-size: 4xs` is emitted and the browser drops the
151	 *                     declaration outright. Same for every `lineHeight`/`letterSpacing` key,
152	 *                     none of which collide with a Chakra default.
153	 *   fontSize: 'l'   → a spacing key that is not a fontSizes key: dropped the same way.
154	 *
155	 * `fontSizes` is the only one of the three with genuine wrong-value collisions; the other two
156	 * only ever drop the declaration. Both outcomes are worth guarding.
157	 *
158	 * Set type with `textStyle` (all 22 Handover styles ARE registered) or var(--zimm-font-*).
159	 * `fontWeight` is deliberately absent: `medium` is a key in both scales and resolves to 500
160	 * either way, so keying it the same way would flag a correct declaration.
161	 */
162	const TYPOGRAPHY_PROPS = new Map<string, Set<string>>([
163	  ['fontSize', new Set([...Object.keys(fontSizes), ...SPACING_KEYS])],
164	  ['lineHeight', new Set([...Object.keys(lineHeights), ...SPACING_KEYS])],
165	  ['letterSpacing', new Set([...Object.keys(letterSpacings), ...SPACING_KEYS])],
166	]);
167	
168	/** Properties that resolve through `theme.space`, where a bare scale key is correct. */
169	const SPACE_SHORTHANDS = new Set(['padding', 'margin', 'inset', 'gap', 'p', 'm']);
170	
171	/** Derived from the registered breakpoints so the two cannot drift apart. */
172	const BREAKPOINT_KEYS = new Set(Object.keys(breakpoints));
173	
174	/**
175	 * True when `n` is a responsive *value* container — an array (`['xl','2xl']`) or a
176	 * breakpoint-keyed object (`{base:'xl', md:'2xl'}`) — rather than a style object. Its keys are
177	 * therefore positions, not property names, and the property name has to come from the parent.
178	 *
179	 * The test is deliberately "are ALL the keys breakpoints?" and not "is ANY key a breakpoint?".
180	 * That is load-bearing: `xl` and `2xl` are keys in `breakpoints` AND in `spacing`, and
181	 * `sm`/`md`/`lg` are keys in `breakpoints` AND in `fontSizes`/`lineHeights`/`letterSpacings`.
182	 * A per-key test cannot tell a responsive map apart from a style object, so only the all-keys
183	 * form works.
184	 *
185	 * A Chakra `sizes`/`variants` map whose every member happens to be named after a breakpoint
186	 * (`sizes: {md: {...}, lg: {...}}`) does read as responsive here, but harmlessly: the level
187	 * below it is a real style object, which re-establishes the property name before any leaf is
188	 * reported.
189	 */
190	const isResponsiveContainer = (n: object): boolean =>
191	  Array.isArray(n) || (Object.keys(n).length > 0 && Object.keys(n).every((k) => BREAKPOINT_KEYS.has(k)));
192	
193	type Found = { recipe: string; path: string; prop: string; value: string };
194	
195	/**
196	 * Recursively walk a style object, including nested media queries, pseudo-selectors and
197	 * responsive containers. `prop` carries the nearest enclosing property name forward so a leaf
198	 * inside a responsive container is attributed to the property, not to `0` or `base`.
199	 */
200	const walk = (node: unknown, recipe: string, path: string, prop: string, hit: (f: Found) => void): void => {
201	  if (node === null || typeof node !== 'object') return;
202	  const responsive = isResponsiveContainer(node);
203	  for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
204	    const here = path ? `${path}.${key}` : key;
205	    const p = responsive ? prop : key;
206	    if (value !== null && typeof value === 'object') {
207	      walk(value, recipe, here, p, hit);
208	    } else if (typeof value === 'string') {
209	      hit({ recipe, path, prop: p, value });
210	    }
211	  }
212	};
213	
214	/**
215	 * `recipe.path.prop: 'value'`. For a responsive hit `path` already ends in the property name
216	 * (the array/breakpoint object sits *under* `fontSize`), so appending `prop` again would read
217	 * `…fontSize.fontSize`.
218	 */
219	const where = (f: Found): string => {
220	  const segments = f.path ? f.path.split('.') : ['baseStyle'];
221	  if (segments[segments.length - 1] !== f.prop) segments.push(f.prop);
222	  return `${f.recipe}.${segments.join('.')}: '${f.value}'`;
223	};
224	
225	/** Default resolution props for a function-form baseStyle — all boolean flags false. */
226	const DEFAULT_STYLE_PROPS: Record<string, unknown> = {
227	  inverse: false,
228	  disabled: false,
229	  hasError: false,
230	  focused: false,
231	  filled: false,
232	  theme,
233	  colorMode: 'light',
234	};
235	
236	/**
237	 * Every combination of DEFAULT_STYLE_PROPS's boolean-valued entries (theme/colorMode held
238	 * fixed) — 2^5 = 32 today. A function-form baseStyle can branch its VALUE, not just its
239	 * shape, on any of these (`top: floated ? '3xs' : '50%'` in zimmTextInput.css.ts), so
240	 * resolving with only the all-false default can leave a branch's value completely unwalked —
241	 * '3xs' shipped exactly this way: `floated` is false under the all-default combo, so the
242	 * guard below never saw the string it was meant to catch. Exhaustive, not sampled: n is
243	 * small enough that 2^n costs nothing, and a missed combination is the whole failure mode.
244	 */
245	const booleanKeys = Object.keys(DEFAULT_STYLE_PROPS).filter((k) => typeof DEFAULT_STYLE_PROPS[k] === 'boolean');
246	const PROP_COMBINATIONS: Record<string, unknown>[] = Array.from({ length: 2 ** booleanKeys.length }, (_, i) => {
247	  const combo = { ...DEFAULT_STYLE_PROPS };
248	  booleanKeys.forEach((key, bit) => {
249	    combo[key] = Boolean(i & (1 << bit));
250	  });
251	  return combo;
252	});
253	
254	/** baseStyle may be a plain object or a function of props (see zimmTextInput). Resolves with
255	 *  the all-false default only — for checks that need just the structural shape (which part
256	 *  keys exist), not every value a branch could produce. */
257	const resolveBaseStyle = (recipe: Record<string, unknown>): unknown => {
258	  const bs = recipe.baseStyle;
259	  if (typeof bs !== 'function') return bs;
260	  return (bs as (p: Record<string, unknown>) => unknown)(DEFAULT_STYLE_PROPS);
261	};
262	
263	/** Every value a function-form baseStyle can produce, across every prop combination. A
264	 *  plain-object baseStyle has only the one "combination" (itself). The value-level guards
265	 *  below walk this, not resolveBaseStyle's single default resolution — see PROP_COMBINATIONS. */
266	const resolveAllBaseStyles = (recipe: Record<string, unknown>): unknown[] => {
267	  const bs = recipe.baseStyle;
268	  if (typeof bs !== 'function') return [bs];
269	  return PROP_COMBINATIONS.map((props) => (bs as (p: Record<string, unknown>) => unknown)(props));
270	};
271	
272	const collect = (): Found[] => {
273	  const found: Found[] = [];
274	  for (const [name, recipe] of Object.entries(components)) {
275	    const r = recipe as unknown as Record<string, unknown>;
276	    for (const resolved of resolveAllBaseStyles(r)) {
277	      walk(resolved, name, '', '', (f) => found.push(f));
278	    }
279	    for (const section of [r.variants, r.sizes]) {
280	      walk(section, name, '', '', (f) => found.push(f));
281	    }
282	  }
283	  // resolveAllBaseStyles calls a function-form baseStyle once per prop combination (32
284	  // today), and most lines don't depend on the varying prop at all — the same Found would
285	  // otherwise appear dozens of times in a failing test's offender list.
286	  const seen = new Set<string>();
287	  return found.filter((f) => {
288	    const key = where(f);
289	    if (seen.has(key)) return false;
290	    seen.add(key);
291	    return true;
292	  });
293	};
